/**
 * Type and field names generated by `@neo4j/graphql` v7, derived from the type definitions.
 *
 * @packageDocumentation
 */

import pluralizeLib from "pluralize";

export function upperFirst(s: string): string {
  return s.charAt(0).toUpperCase() + s.slice(1);
}

/**
 * `camelcase` as used by v7 for entity names: `Movie` → `movie`, `OrderLine` → `orderLine`,
 * `HTTPServer` → `httpServer`, `my_type` → `myType`. Leading underscores are kept by the callers.
 */
export function camelCase(input: string): string {
  const s = input.replace(/^_+/, "");
  const words = s
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/([A-Z]+)([A-Z][a-z])/g, "$1 $2")
    .split(/[\s_\-.]+/)
    .filter(Boolean);
  return words.map((w, i) => (i === 0 ? w.toLowerCase() : upperFirst(w.toLowerCase()))).join("");
}

function leadingUnderscores(name: string): string {
  return /^_+/.exec(name)?.[0] ?? "";
}

/** `pluralize` (the npm package v7 uses), exposed for descriptions such as "related People". */
export function pluralize(word: string): string {
  return pluralizeLib(word);
}

/** Root field plural: `Movie` → `movies`, `Person` → `people`. `@plural(value)` wins. */
export function entityPlural(name: string, pluralOverride?: string): string {
  if (pluralOverride !== undefined)
    return `${leadingUnderscores(pluralOverride)}${camelCase(pluralOverride)}`;
  return `${leadingUnderscores(name)}${pluralizeLib(camelCase(name))}`;
}

/** v7 `singular`: `Movie` → `movie` (subscription root fields `movieCreated`, …). */
export function entitySingular(name: string): string {
  return `${leadingUnderscores(name)}${camelCase(name)}`;
}

/** Names v7 generates for the subscriptions of a node type. */
export function subscriptionNames(name: string) {
  const singular = entitySingular(name);
  const pascal = upperFirst(singular);
  return {
    payload: `${name}EventPayload`,
    where: `${name}SubscriptionWhere`,
    CREATED: {
      field: `${singular}Created`,
      type: `${pascal}CreatedEvent`,
      payload: `created${pascal}`,
    },
    UPDATED: {
      field: `${singular}Updated`,
      type: `${pascal}UpdatedEvent`,
      payload: `updated${pascal}`,
    },
    DELETED: {
      field: `${singular}Deleted`,
      type: `${pascal}DeletedEvent`,
      payload: `deleted${pascal}`,
    },
  } as const;
}
